export type IconName = (typeof ICON_NAMES)[keyof typeof ICON_NAMES];
export type IconCategory =
  | "actions"
  | "animals"
  | "buildings"
  | "commerce"
  | "communication"
  | "data"
  | "development"
  | "devices"
  | "editing"
  | "education"
  | "entertainment"
  | "feedback"
  | "food"
  | "health"
  | "industry"
  | "interface"
  | "lifestyle"
  | "media"
  | "nature"
  | "navigation"
  | "people"
  | "science"
  | "security"
  | "shapes"
  | "sports"
  | "symbols"
  | "time"
  | "tools"
  | "transport";
export type OpticalClass = "regular" | "wide" | "tall" | "directional" | "compound" | "line-symbol";
export type IconTier = "core" | "extended";
export type IconDirection = "none" | "mirror";

export interface IconCatalogEntry {
  readonly name: IconName;
  readonly category: IconCategory;
  readonly opticalClass: OpticalClass;
  readonly tier: IconTier;
  readonly rtl: IconDirection;
}

